// Embed the bundled renderer as string constants so the card frame needs no network or asset route.
import { readFileSync, writeFileSync } from 'node:fs'

const js = readFileSync(new URL('../island/dist/island.js', import.meta.url), 'utf8')
const css = readFileSync(new URL('../island/dist/island.css', import.meta.url), 'utf8')
writeFileSync(new URL('../src/client/island-assets.generated.ts', import.meta.url), [
  '// Generated by scripts/embed-island.mjs from island/dist; do not edit.',
  `/** Bundled React 19 + Astryx renderer script. */\nexport const ISLAND_JS: string = ${JSON.stringify(js)}`,
  `/** Bundled Astryx stylesheet. */\nexport const ISLAND_CSS: string = ${JSON.stringify(css)}`,
  '',
].join('\n'))
